public static void TestDecompressor(ж<testing.T> t) {
    GoFrame ᒐ = default;
    try {
        var b = @new<bytes.Buffer>();
        foreach (var (_, tt) in range(zlibTests)) {
            var @in = bytes.NewReader(tt.compressed);
            var (zr, err) = NewReaderDict(new zlib_test_package.bytes_ReaderжReader(@in), tt.dict);
            if (err != nil) {
                if (!AreEqual(err, tt.err)) {
                    t.Errorf("%s: NewReader: %s", tt.desc, err);
                }
                continue;
            }
            var zrʗ1 = zr;
            defer(() => zrʗ1.Close(), ref ᒐ);

            // Read and verify correctness of data.
            b.Reset();
            (var n, err) = io.Copy(new zlib_test_package.bytes_BufferжWriter(b), zr);
            if (err != nil) {
                if (!AreEqual(err, tt.err)) {
                    t.Errorf("%s: io.Copy: %v want %v", tt.desc, err, tt.err);
                }
                continue;
            }
            @string s = b.String();
            if (s != tt.raw) {
                t.Errorf("%s: got %d-byte %q want %d-byte %q", tt.desc, n, s, len(tt.raw), tt.raw);
            }

            // Check for sticky errors.
            var (nΔ1, errΔ1) = zr.Read([0]); if (nΔ1 != 0 || !AreEqual(errΔ1, io.EOF)) {
                t.Errorf("%s: Read() = (%d, %v), want (0, io.EOF)", tt.desc, nΔ1, errΔ1);
            }
            var errΔ2 = zr.Close(); if (errΔ2 != nil) {
                t.Errorf("%s: Close() = %v, want nil", tt.desc, errΔ2);
            }
        }
    }
    catch (Exception ᒐex) when (GoFrame.IsPanic(ᒐex, out PanicException? ᒐp)) { GoFrame.Capture(ᒐp); }
    finally { ᒐ.Run(); }
}

